# bash completion for sm. Generated by `sm completion bash`: run it again after upgrading sm.

# Install: source it from ~/.bashrc, or save it as ~/.local/share/bash-completion/completions/sm.

_sm_children() {
    case $1 in
        '') _sm_r='convert info list get find diff deps init validate rename remove move bpa set add translations perspective script lint format connect profile session query preview deploy data refresh test completion mcp vertipaq schemacheck interactive pkg csharp' ;;
        'bpa') _sm_r='rules' ;;
        'bpa rules') _sm_r='list show add remove ignore unignore' ;;
        'translations') _sm_r='export import cultures' ;;
        'perspective') _sm_r='add remove list' ;;
        'script') _sm_r='export apply' ;;
        'profile') _sm_r='set list show remove' ;;
        'session') _sm_r='show list clear prune' ;;
        'data') _sm_r='init check info embed' ;;
        'test') _sm_r='run init snapshot compare list' ;;
        'pkg') _sm_r='list search show install update remove' ;;
        *) _sm_r='' ;;
    esac
}

