# Add the lines of $1 to COMPREPLY, escaped for the command line unless the word is quoted, and
# less what bash has already split off at ':' or '=' (it replaces only the rest).
_sm_reply() {
    local c strip=${_sm_cur%"${COMP_WORDS[COMP_CWORD]}"}
    while IFS= read -r c; do
        [[ -n $c ]] || continue
        if [[ $_sm_cur != [\'\"]* ]]; then printf -v c '%q' "$c"; fi
        COMPREPLY+=("${c#"$strip"}")
    done <<< "$1"
}

_sm() {
    local _sm_r _sm_cur words=() i w line trimmed node='' pos=0 skip='' kind='' children=''
    COMPREPLY=()
    # The words up to the cursor, joining back what bash split at ':' and '=' (measure:Sales/Total).
    line=${COMP_LINE:0:COMP_POINT}
    for ((i = 0; i <= COMP_CWORD; i++)); do
        w=${COMP_WORDS[i]}
        trimmed=${line#"${line%%[![:space:]]*}"}
        if ((i > 0)) && [[ ${#trimmed} -eq ${#line} ]] && ((${#words[@]} > 0)); then
            words[${#words[@]}-1]+=$w
        else
            words+=("$w")
        fi
        line=${trimmed#"$w"}
    done
    _sm_cur=${words[${#words[@]}-1]}
    for ((i = 1; i < ${#words[@]} - 1; i++)); do
        w=${words[i]}
        if [[ -n $skip ]]; then skip=''; continue; fi
        _sm_children "$node"
        if [[ " $_sm_r " == *" $w "* ]]; then node=${node:+$node }$w; pos=0; continue; fi
        if [[ $w == -?* ]]; then
            _sm_value "$node" "$w"
            [[ -n $_sm_r ]] && skip=1
            continue
        fi
        pos=$((pos + 1))
    done
    if [[ -n $skip ]]; then
        _sm_value "$node" "${words[${#words[@]}-2]}"; kind=$_sm_r
    elif [[ $_sm_cur == -* ]]; then
        _sm_options "$node"
        COMPREPLY=($(compgen -W "$_sm_r" -- "$_sm_cur"))
        return
    else
        _sm_positional "$node" "$pos"; kind=$_sm_r
        if ((pos == 0)); then _sm_children "$node"; children=$_sm_r; fi
    fi
    if [[ -n $children ]]; then COMPREPLY=($(compgen -W "$children" -- "$_sm_cur")); fi
    case $kind in
        choice\ *) COMPREPLY+=($(compgen -W "${kind#choice }" -- "$_sm_cur")) ;;
        dyn) _sm_reply "$("${COMP_WORDS[0]}" __complete --quoted "--current=$_sm_cur" -- "${words[@]:1:${#words[@]}-2}" 2>/dev/null)" ;;
        dir) if ((${#COMPREPLY[@]} == 0)) && type compopt &>/dev/null; then compopt -o dirnames; fi ;;
    esac
    # Nothing else to offer for a path: bash completes file names (complete -o default).
}

complete -o bashdefault -o default -F _sm sm
